/* ------------------------------------------------------------------ public API (in-process) */

/** What other modules may call in-process: `ctx.use('content')` (or `ctx.tryUse` for an optional dependency). */
export interface ContentPublicApi {
  /** Policy versions in effect at a moment. Checkout and orders store these ids on the order so the order keeps the purchase terms and return policy accepted at purchase (plan ch. 3, 8). Used by: checkout, orders, returns, sellers. */
  currentPolicyVersions(keys: string[], at?: string): Promise<PolicyVersionRef[]>;
  /** Exact text of a version, e.g. for order details and disputes. Used by: orders, support, returns. */
  getPolicyVersion(versionId: string): Promise<PolicyVersion>;
  /** Suggested articles for an order problem or case category. Used by: support, graphql. */
  helpArticlesFor(topic: string, limit: number): Promise<HelpArticleSummary[]>;
  /** Public URL and status of a campaign page, used for ad destination link checks. Used by: advertising, promotions. */
  pageLink(pageId: string): Promise<{ url: string, status: string, publishAt?: string, unpublishAt?: string } | null>;
  /** Published homepage sections in order with schedules applied (showFrom/removeAt), unavailable products hidden and ended promotions removed (GET /home). Product, offer, deal and stock data are resolved by their owning modules. Used by: graphql. */
  getHomePage(ctx: { customerId?: string, device?: string, at?: string }): Promise<Homepage>;
  /** The draft or live homepage as customers will see it at a given time on desktop or phone (POST /homepage/preview, a read). Used by: graphql. */
  previewHomePage(req: PreviewRequest): Promise<Homepage>;
  /** A published campaign page, collection, About or landing page by slug, with blocks resolved (GET /pages/{slug}). Used by: graphql. */
  getStorePage(slug: string): Promise<StorePage | null>;
  /** The draft of a page as customers will see it (POST /pages/{id}/preview, a read). Used by: graphql. */
  previewPage(pageId: string): Promise<StorePage>;
  /** Products of a collection page by its selection rule or manual list, page by page, optionally limited to a category tab (GET /pages/{slug}/products). Used by: graphql. */
  collectionProducts(pageId: string, opts: { categoryId?: string, paging: common.PageInput }): Promise<common.Page<ProductTile>>;
  /** Help Center home: topics, popular articles, popular searches, contact channels and the seller-first note (GET /help). Used by: graphql. */
  getHelpCenter(audience: 'customer' | 'seller'): Promise<HelpHome>;
  /** A published help article with effective and updated dates, related articles and actions (GET /help/articles/{slug}). Used by: graphql. */
  getHelpArticle(slug: string): Promise<HelpArticle | null>;
  /** Published Help articles whose policyKeys include the policy (e.g. returns), so a policy change preview can say how many need review. Used by: returns. */
  countHelpArticlesForPolicy(policyKey: string): Promise<{ count: number, articleIds: string[] }>;
  /** Announcements for Seller Center, newest first: policy versions with notifySellers that are scheduled or current (audience seller or both), from policy_versions. No separate announcements table at launch. Used by: reports, graphql. */
  sellerAnnouncements(opts: { since?: string, limit: number }): Promise<SellerAnnouncement[]>;
  /** Homepage sections and pages linked to a promotion (linkedPromotionId, or a deals SourceRule with that campaignId), for the campaign detail in promotions and ad destination checks Used by: promotions, advertising, graphql. */
  contentForCampaign(campaignId: string): Promise<{ sections: { id: string, kind: string, heading?: string, status: string }[], pages: { id: string, slug: string, title: string, status: string, url: string }[] }>;
}

/* ------------------------------------------------------------------ tables (row types) */

/** Rows of this module's spec tables, as repositories read them from its collections (`content.<table>`, ctx.mongo.table(name)). */
export interface ContentDb {
  /** Homepage sections (draft state); ad positions are rows with kind ad_position and a placement key */
  home_sections: {
    id: string;
    kind: string;
    heading: string | null;
    subheading: string | null;
    config: Json;
    linked_promotion_id: string | null;
    linked_page_id: string | null;
    ad_placement_key: string | null;
    show_from: Date | null;
    remove_at: Date | null;
    time_zone: string;
    owner_staff_id: string | null;
    owner_role: string | null;
    status: string;
    draft_position: number;
    removed_reason: string | null;
    updated_by: string;
    updated_at: Date;
  };
  /** Campaign pages, collections, About and landing pages */
  pages: {
    id: string;
    kind: string;
    collection_kind: string | null;
    slug: string;
    title: string;
    brand_id: string | null;
    owner_staff_id: string | null;
    linked_promotion_id: string | null;
    status: string;
    publish_at: Date | null;
    unpublish_at: Date | null;
    time_zone: string;
    live_version_id: string | null;
    draft_version_id: string | null;
    removal: Json | null;
    created_at: Date;
    updated_at: Date;
  };
  /** Immutable snapshots of homepage layouts, pages and articles. Restore copies a snapshot into a new version. */
  versions: {
    id: string;
    entity: 'homepage' | 'page' | 'article' | 'news';
    entity_id: string;
    number: number;
    state: string;
    snapshot: Json;
    summary: string | null;
    author_kind: string;
    author_id: string | null;
    restored_from: number | null;
    review_state: 'not_submitted' | 'in_review' | 'approved' | 'changes_requested' | null;
    submitted_by: string | null;
    submitted_at: Date | null;
    reviewed_by: string | null;
    reviewed_at: Date | null;
    review_note: string | null;
    created_at: Date;
    published_at: Date | null;
  };
  help_categories: {
    id: string;
    slug: string;
    name: string;
    icon: string | null;
    description: string | null;
    position: number;
    visible: boolean;
    audience: string;
  };
  help_articles: {
    id: string;
    slug: string;
    category_id: string;
    title: string;
    summary: string | null;
    audience: string;
    topics: Json;
    related_ids: Json;
    policy_keys: Json;
    featured: boolean;
    popular_search: string | null;
    owner_staff_id: string | null;
    status: string;
    publish_at: Date | null;
    unpublish_at: Date | null;
    effective_at: Date | null;
    review_due_at: Date | null;
    live_version_id: string | null;
    draft_version_id: string | null;
    views: number;
    /** generated from the live version: title, summary, topics and body as plain text, matched by help search */
    search: string | null;
    updated_at: Date;
  };
  article_feedback: {
    id: string;
    article_id: string;
    helpful: boolean;
    comment: string | null;
    visitor_key: string;
    customer_id: string | null;
    at: Date;
  };
  policies: {
    id: string;
    /** URL slug */
    key: string;
    kind: 'returns' | 'shipping' | 'privacy' | 'purchase_terms' | 'seller_rules' | 'advertising' | 'cookies' | 'other';
    title: string;
    owner_staff_id: string;
    editor_staff_id: string | null;
    audience: 'customer' | 'seller' | 'both';
  };
  /** Never edited after approval; orders reference these ids */
  policy_versions: {
    id: string;
    policy_id: string;
    version: string;
    state: string;
    title: string;
    body: string;
    tables: Json | null;
    effective_at: Date | null;
    change_summary: string | null;
    impact: string;
    notify_customers: boolean;
    notify_sellers: boolean;
    approval_request_id: string | null;
    created_by: string;
    created_at: Date;
    published_at: Date | null;
  };
  policy_approvals: {
    id: string;
    policy_version_id: string;
    role: string;
    reviewer_id: string | null;
    state: string;
    note: string | null;
    at: Date | null;
  };
  /** Header and footer link groups (versioned through versions with entity page kind 'navigation' is not needed; edits are audited) */
  navigation: {
    id: string;
    area: 'header' | 'footer' | 'service_strip';
    group_title: string | null;
    position: number;
    label: string;
    url: string;
    kind: string;
    /** service_strip only */
    text: string | null;
    active_from: Date | null;
    active_until: Date | null;
  };
  /** Staff-editable news categories (filter chips in the store) */
  news_categories: {
    id: string;
    slug: string;
    name: string;
    icon: string | null;
    position: number;
    visible: boolean;
    /** old slugs that still filter */
    previous_slugs: Json;
  };
  /** News for customers; content lives in versions (entity news), these columns follow the live version */
  news_posts: {
    id: string;
    slug: string;
    /** old slugs that still open the post */
    previous_slugs: Json;
    category_id: string;
    title: string;
    summary: string;
    owner_staff_id: string | null;
    status: string;
    pinned: boolean;
    pinned_at: Date | null;
    publish_at: Date | null;
    unpublish_at: Date | null;
    archive_at: Date | null;
    /** first publication */
    published_at: Date | null;
    live_version_id: string | null;
    draft_version_id: string | null;
    updated_at: Date;
  };
  /** Publication, schedule, unpublish, correction and removal actions with reasons */
  content_log: {
    id: string;
    entity: string;
    entity_id: string;
    action: string;
    reason: string | null;
    actor_kind: string;
    actor_id: string | null;
    at: Date;
  };
}

